def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    vals, cnts = np.unique(g, return_counts=True)
    order = [int(v) for v in vals[np.argsort(-cnts)]]
    regions = order[:2]
    seeds = [(y, x) for y in range(H) for x in range(W) if g[y, x] not in regions]
    mapping = {}
    for (y, x) in seeds:
        c = {}
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                yy, xx = y + dy, x + dx
                if (dy or dx) and 0 <= yy < H and 0 <= xx < W and g[yy, xx] in regions:
                    c[int(g[yy, xx])] = c.get(int(g[yy, xx]), 0) + 1
        if c:
            mapping[max(c, key=c.get)] = int(g[y, x])
    out = g.copy()
    for (y, x) in seeds:
        for dy, dx in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
            yy, xx = y + dy, x + dx
            while 0 <= yy < H and 0 <= xx < W:
                v = int(g[yy, xx])
                if v in mapping:
                    out[yy, xx] = mapping[v]
                yy += dy
                xx += dx
        emit(out.copy(), f"Drew the four diagonal rays from seed at ({y},{x}), recolouring each region cell by the region->seed colour map {mapping}.")
    emit(out.copy(), "Final grid: all seed diagonals drawn.")
    return out
